#include "cgal_base.hh"
#include "mesh.hh"
#include "power_diagram.hh"

Mesh<Point, double> power_diagram_edges(RT const &rt, double threshold) {
    Mesh<Point, double> result;

    for (RT::Finite_facets_iterator fit = rt.finite_facets_begin(); fit != rt.finite_facets_end(); ++fit) {
        RT::Facet f = *fit;
        if (!is_large_facet(rt, f, threshold)) {
            continue;
        }

        RT::Cell_handle c1 = f.first;
        RT::Cell_handle c2 = c1->neighbor(f.second);

        if (rt.is_infinite(c1) || rt.is_infinite(c2)) {
            continue;
        }

        Point dual1 = rt.dual(c1);
        Point dual2 = rt.dual(c2);

        unsigned v1_index = result.vertices.size();
        result.vertices.push_back(dual1);

        unsigned v2_index = result.vertices.size();
        result.vertices.push_back(dual2);

        std::vector<unsigned> edge = {v1_index, v2_index};
        result.push_back(edge, 0.0);
    }

    return result;
}

